def _estimate_pdf_from_priors(p: jnp.ndarray, q: jnp.ndarray) -> jnp.ndarray:
  """Estimates smooth pdf with Gaussian kernel.

  Args:
    p: Samples.
    q: Samples.

  Returns:
    A density vector.
